def trap(h):
    l, r = 0, len(h) - 1
    lmax = rmax = water = 0
    while l < r:
        if h[l] < h[r]:
            lmax = max(lmax, h[l]); water += lmax - h[l]; l += 1
        else:
            rmax = max(rmax, h[r]); water += rmax - h[r]; r -= 1
    return water

solution.cpp:
int trap(const vector<int>& h) {
    int l = 0, r = (int)h.size() - 1, lmax = 0, rmax = 0, water = 0;
    while (l < r) {
        if (h[l] < h[r]) { lmax = max(lmax, h[l]); water += lmax - h[l++]; }
        else            { rmax = max(rmax, h[r]); water += rmax - h[r--]; }
    }
    return water;
}

