def longest_unique(s):
    last, left, best = {}, 0, 0
    for i, c in enumerate(s):
        if c in last and last[c] >= left:
            left = last[c] + 1
        last[c] = i
        best = max(best, i - left + 1)
    return best

solution.go:
func longestUnique(s string) int {
    last := map[rune]int{}
    left, best := 0, 0
    for i, c := range s {
        if j, ok := last[c]; ok && j >= left {
            left = j + 1
        }
        last[c] = i
        if i-left+1 > best {
            best = i - left + 1
        }
    }
    return best
}

