    a, b = 1, 1  # ways(0), ways(1)
    for _ in range(n - 1):
        a, b = b, (a + b) % mod
    return b

solution.c:
long long countWays(int n) {
    const long long MOD = 1000000007LL;
    long long a = 1, b = 1;
    for (int i = 2; i <= n; i++) { long long c = (a + b) % MOD; a = b; b = c; }
    return b;
}

